insert into public.blog_posts (slug, locale, category, title, excerpt, published_at, read_time, author, tags, intro, sections, conclusion, image, faqs, featured, published, seo_title, seo_description, sort_order) values ('trucos-para-optimizar-tu-wordpress', 'es', 'WordPress', '10 trucos para optimizar el rendimiento de tu sitio WordPress', 'El rendimiento de un sitio web es importante tanto para los usuarios como para el posicionamiento en los motores de búsqueda. Los sitios web lentos pueden disuadir a los usuarios y afectar la experiencia de usuario, y ta', '2024-06-02', '3 min', 'Equipo Terranode', '["caché", "CDN", "JavaScript", "optimización"]'::jsonb, 'El rendimiento de un sitio web es importante tanto para los usuarios como para el posicionamiento en los motores de búsqueda. Los sitios web lentos pueden disuadir a los usuarios y afectar la experiencia de usuario, y también pueden afectar negativamente el posicionamiento en los motores de búsqueda. Por lo tanto, es importante asegurarse de que tu sitio WordPress esté optimizado para obtener el mejor rendimiento…', '[]'::jsonb, 'Esperamos que esta guía te haya sido de utilidad. Si tienes dudas durante la implementación, nuestro equipo de soporte técnico está disponible 24/7 para ayudarte.', NULL, '[]'::jsonb, false, true, '10 trucos para optimizar el rendimiento de tu sitio WordPress', 'El rendimiento de un sitio web es importante tanto para los usuarios como para el posicionamiento en los motores de búsqueda. Los sitios web lentos pueden…', 0)
