insert into public.blog_posts (slug, locale, category, title, excerpt, published_at, read_time, author, tags, intro, sections, conclusion, image, faqs, featured, published, seo_title, seo_description, sort_order) values ('guia-para-implementar-seguridad-en-un-servidor-linux', 'es', 'Infrastructure', 'Guía para Implementar Seguridad en un Servidor Linux', 'La seguridad en los servidores Linux es un tema fundamental para garantizar la integridad, confidencialidad y disponibilidad de los datos. Esta guía cubrirá desde las configuraciones básicas hasta estrategias avanzadas p', '2024-12-28', '4 min', 'Equipo Terranode', '["Infrastructure"]'::jsonb, 'La seguridad en los servidores Linux es un tema fundamental para garantizar la integridad, confidencialidad y disponibilidad de los datos. Esta guía cubrirá desde las configuraciones básicas hasta estrategias avanzadas para proteger un servidor Linux, incluyendo comandos, configuraciones y mejores prácticas.', '[{"h": "1.1 Actualiza tu Sistema Operativo", "body": "Ejecuta los siguientes comandos:\n\nsudo apt update && sudo apt upgrade -y\n\nsudo yum update -y\n\nsudo apt install unattended-upgrades\nsudo dpkg-reconfigure --priority=low unattended-upgrades"}, {"h": "1.2 Cambiar el Puerto por Defecto de SSH", "body": "Edita el archivo de configuración de SSH:\n\nsudo nano /etc/ssh/sshd_config\n\nPort 2222\n\nsudo systemctl restart sshd\n\nsudo ufw allow 2222/tcp"}, {"h": "1.3 Crear Usuarios con Privilegios Limitados", "body": "Crea un usuario:\n\nsudo adduser nombre_usuario\n\nsudo usermod -aG sudo nombre_usuario\n\nsudo nano /etc/ssh/sshd_config\n\nPermitRootLogin no\n\nsudo systemctl restart sshd"}, {"h": "2.1 Configurar UFW (Uncomplicated Firewall)", "body": "Habilita UFW y configura las reglas:\n\nsudo ufw allow 2222/tcp # Puerto SSH\nsudo ufw allow http\nsudo ufw allow https\nsudo ufw enable\n\nsudo ufw status"}, {"h": "2.2 Configurar Firewalld (Distribuciones Red Hat)", "body": "Inicia y habilita el servicio:\n\nsudo systemctl start firewalld\nsudo systemctl enable firewalld\n\nsudo firewall-cmd --permanent --add-port=2222/tcp\nsudo firewall-cmd --permanent --add-service=http\nsudo firewall-cmd --permanent --add-service=https\nsudo firewall-cmd --reload"}, {"h": "2.3 Mejorar la Seguridad del Firewall", "body": "sudo ufw allow from 192.168.1.0/24 to any port 2222"}, {"h": "3.1 Configurar Autenticación de Llaves SSH", "body": "• Genera un par de llaves en tu máquina local:\n\nssh-keygen -t rsa -b 4096\n\n• Copia la clave pública al servidor:\n\nssh-copy-id -i ~/.ssh/id_rsa.pub usuario@ip_del_servidor"}, {"h": "3.2 Deshabilitar Autenticación por Contraseña", "body": "Edita el archivo de configuración de SSH:\n\nsudo nano /etc/ssh/sshd_config\n\nPasswordAuthentication no\n\nsudo systemctl restart sshd"}, {"h": "4.1 Fail2Ban", "body": "• Instala Fail2Ban:\n\nsudo apt install fail2ban -y\n\n• Configura la protección para SSH:\n\nsudo nano /etc/fail2ban/jail.local\n\n enabled = true\nport = 2222\nfilter = sshd\nlogpath = /var/log/auth.log\nmaxretry = 5\n\nsudo systemctl restart fail2ban"}, {"h": "4.2 DDoS Deflate", "body": "• Descarga e instala DDoS Deflate:\n\nwget https://github.com/jgmdev/ddos-deflate/archive/master.zip\nunzip master.zip\ncd ddos-deflate-master\nsudo ./install.sh\n\n• Configura el archivo de configuración principal:\n\nsudo nano /usr/local/ddos/ddos.conf\n\n• Activa el servicio:\n\nsudo /usr/local/ddos/ddos.sh -c"}, {"h": "4.3 RKHunter y ClamAV", "body": "• Instala RKHunter:\n\nsudo apt install rkhunter -y\nsudo rkhunter --update\nsudo rkhunter --checkall\n\n• Instala ClamAV y realiza un escaneo:\n\nsudo apt install clamav -y\nsudo freshclam\nsudo clamscan -r /home"}, {"h": "5.1 Configurar Logwatch", "body": "• Instala Logwatch:\n\nsudo apt install logwatch -y\n\n• Configura informes automáticos:\n\nsudo nano /etc/cron.daily/00logwatch\n\n/usr/sbin/logwatch --output mail --mailto tuemail@example.com --detail high"}, {"h": "5.2 Instalar y Configurar Auditd", "body": "• Instala Auditd:\n\nsudo apt install auditd -y\n\n• Define reglas personalizadas para monitorear cambios críticos:\n\nsudo nano /etc/audit/audit.rules\n\n-w /etc/passwd -p wa -k passwd_changes\n-w /etc/ssh/sshd_config -p wa -k ssh_changes\n\nsudo systemctl restart auditd"}, {"h": "6.1 Configurar Backups Automatizados", "body": "Ejemplo:\n\nrsync -avz /ruta/del/directorio usuario@backup-server:/ruta/de/backup\n\ncrontab -e\n\n0 2 * * * rsync -avz /ruta/del/directorio usuario@backup-server:/ruta/de/backup"}, {"h": "6.2 Configurar Snapshots con LVM", "body": "sudo lvcreate --size 1G --snapshot --name backup_nombre /dev/volume_group/logical_volume"}, {"h": "Resumen", "body": "• Asegurar el acceso SSH mediante cambios en el puerto predeterminado y autenticación por llaves.\n• Configurar cortafuegos robustos con UFW o Firewalld.\n• Implementar herramientas de protección como Fail2Ban, DDoS Deflate, RKHunter y ClamAV.\n• Monitorear la actividad del servidor con Logwatch y Auditd.\n• Establecer una estrategia de respaldo confiable usando rsync y snapshots con LVM."}]'::jsonb, 'Esperamos que esta guía te haya sido de utilidad. Si tienes dudas durante la implementación, nuestro equipo de soporte técnico está disponible 24/7 para ayudarte.', NULL, '[]'::jsonb, false, true, 'Guía para Implementar Seguridad en un Servidor Linux', 'La seguridad en los servidores Linux es un tema fundamental para garantizar la integridad, confidencialidad y disponibilidad de los datos. Esta guía…', 0)
