insert into public.blog_posts (slug, locale, category, title, excerpt, published_at, read_time, author, tags, intro, sections, conclusion, image, faqs, featured, published, seo_title, seo_description, sort_order) values ('reverse-proxy-para-ocultar-la-ip-del-servidor', 'es', 'Linux', 'Implementación de un Reverse Proxy para Ocultar la IP del Servidor', 'En un entorno donde la seguridad y el anonimato son prioritarios, el uso de un reverse proxy es una estrategia fundamental. Este componente actúa como intermediario entre los usuarios y el servidor, ocultando la IP de es', '2024-12-28', '3 min', 'Equipo Terranode', '["Linux"]'::jsonb, 'En un entorno donde la seguridad y el anonimato son prioritarios, el uso de un reverse proxy es una estrategia fundamental. Este componente actúa como intermediario entre los usuarios y el servidor, ocultando la IP de este último y mejorando la seguridad general del sistema. Además, podría salvarte de intentos de hackeo y darte un respiro – literalmente – al balancear la carga del tráfico. 😅', '[{"h": "Lo que Necesitarás", "body": "• Dos servidores: Uno para actuar como reverse proxy (Nginx) y otro como backend.\n• Acceso SSH a ambos servidores.\n• Un dominio para configurar HTTPS (opcional pero recomendado)."}, {"h": "Ventajas de Usar un Reverse Proxy", "body": "• Ocultación de la IP del Servidor: La dirección IP del servidor se mantiene privada, ya que los clientes interactúan solo con el proxy.\n• Protección contra Ataques Directos: Un reverse proxy puede filtrar el tráfico malicioso antes de que alcance el servidor principal.\n• Balanceo de Carga: Distribuye las solicitudes entre varios servidores para mejorar el rendimiento.\n• Caching: Almacena temporalmente recursos estáticos, reduciendo la carga en el servidor principal. Además, hace que tus usuarios piensen que todo es más rápido de lo que realmente es. 😜"}, {"h": "Paso 1: Instalación de Nginx", "body": "sudo apt update\nsudo apt install nginx -y\n\nsudo yum install nginx -y"}, {"h": "Paso 2: Configuración Básica de Reverse Proxy", "body": "sudo nano /etc/nginx/sites-available/default\n\nserver {\n listen 80;\nserver_name tu-dominio.com;\nlocation / {\n proxy_pass http://127.0.0.1:8080;\n proxy_set_header Host $host;\n proxy_set_header X-Real-IP $remote_addr;\n proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n }\n}\n\nserver_name tu-dominio.com;\n\nlocation / {\n proxy_pass http://127.0.0.1:8080;\n proxy_set_header Host $host;\n proxy_set_header X-Real-IP $remote_addr;\n proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\n }\n}\n\nsudo nginx -t\n\nsudo systemctl restart nginx"}, {"h": "Paso 3: Habilitar HTTPS con Let''s Encrypt", "body": "Instala Certbot:\n\nsudo apt install certbot python3-certbot-nginx -y\n\nsudo certbot --nginx -d tu-dominio.com\n\nsudo crontab -e\n\n0 0 * * * certbot renew --quiet"}, {"h": "Filtrado de Tráfico Malicioso", "body": "location / {\n proxy_pass http://127.0.0.1:8080;\n deny 192.168.1.1; # Bloquea una IP específica\n allow 192.168.1.0/24; # Permite solo un rango de IPs\n proxy_set_header Host $host;\n proxy_set_header X-Real-IP $remote_addr;\n}"}, {"h": "Limitación de Solicitudes", "body": "http {\n limit_req_zone $binary_remote_addr zone=one:10m rate=30r/s;\nserver {\n location / {\n limit_req zone=one burst=10;\n proxy_pass http://127.0.0.1:8080;\n }\n }\n}\n\nserver {\n location / {\n limit_req zone=one burst=10;\n proxy_pass http://127.0.0.1:8080;\n }\n }\n}"}, {"h": "Uso de ModSecurity con Nginx", "body": "• Instala ModSecurity:\n\nsudo apt install libnginx-mod-security -y\n\n• Habilita el módulo en Nginx:\n\nsudo nano /etc/nginx/nginx.conf\n\nload_module modules/ngx_http_modsecurity_module.so;\n\n• Configura ModSecurity:\n\nsudo nano /etc/nginx/modsec/main.conf"}, {"h": "Configuración de Balanceo de Carga", "body": "Ejemplo de configuración:\n\nupstream backend {\n server 192.168.1.101;\n server 192.168.1.102;\n}\nserver {\n listen 80;\n location / {\n proxy_pass http://backend;\n }\n}\n\nserver {\n listen 80;\n location / {\n proxy_pass http://backend;\n }\n}"}, {"h": "Consideraciones de Seguridad Adicionales", "body": "• Habilita Firewall: Usa UFW o Firewalld para permitir solo tráfico a los puertos necesarios.\n\nsudo ufw allow 80/tcp\nsudo ufw allow 443/tcp\n\n• Monitoreo del Sistema: Implementa herramientas como Fail2Ban para proteger contra intentos de fuerza bruta.\n\nsudo apt install fail2ban -y\n\n• Actualizaciones Regulares: Mantén Nginx y los certificados SSL actualizados."}, {"h": "Resumen", "body": "• Anonimato: Oculta la IP real del servidor backend.\n• Seguridad Mejorada: Filtra tráfico malicioso y protege contra ataques directos.\n• Rendimiento: Implementa caching y balanceo de carga."}]'::jsonb, 'Esperamos que esta guía te haya sido de utilidad. Si tienes dudas durante la implementación, nuestro equipo de soporte técnico está disponible 24/7 para ayudarte.', NULL, '[]'::jsonb, false, true, 'Implementación de un Reverse Proxy para Ocultar la IP del…', 'En un entorno donde la seguridad y el anonimato son prioritarios, el uso de un reverse proxy es una estrategia fundamental. Este componente actúa como…', 0)
