insert into public.blog_posts (slug, locale, category, title, excerpt, published_at, read_time, author, tags, intro, sections, conclusion, image, faqs, featured, published, seo_title, seo_description, sort_order) values ('fail2ban-proteccion-fuerza-bruta', 'es', 'Security', 'Instalación y Configuración de Fail2Ban para Evitar Fuerza Bruta', 'La seguridad de un servidor Linux es esencial, especialmente contra ataques de fuerza bruta que buscan acceder a servicios como SSH, HTTP o FTP. Fail2Ban es una herramienta poderosa que monitoriza los registros del siste', '2024-12-28', '3 min', 'Equipo Terranode', '["Security"]'::jsonb, 'La seguridad de un servidor Linux es esencial, especialmente contra ataques de fuerza bruta que buscan acceder a servicios como SSH, HTTP o FTP. Fail2Ban es una herramienta poderosa que monitoriza los registros del sistema y bloquea automáticamente las IPs sospechosas. En esta guía aprenderás cómo instalarlo, configurarlo y asegurarte de que tu servidor esté protegido, todo explicado con un toque de humor. 😅', '[{"h": "Lo que Necesitarás", "body": "• Un servidor Linux funcional (Ubuntu, Debian, CentOS, etc.).\n• Acceso SSH con permisos sudo.\n• Conocimientos básicos sobre edición de archivos y terminal."}, {"h": "Ventajas de Usar Fail2Ban", "body": "• Automatización de Bloqueos: No necesitas revisar manualmente los logs.\n• Configuración Flexible: Personaliza las reglas para diferentes servicios.\n• Protección Multiservicio: Compatible con SSH, HTTP, FTP, y más.\n• Mejora del Rendimiento: Reduce la carga de intentos maliciosos en el servidor."}, {"h": "Paso 1: Instalación del Paquete", "body": "sudo apt update\nsudo apt install fail2ban -y\n\nsudo yum install epel-release -y\nsudo yum install fail2ban -y"}, {"h": "Paso 2: Verificar la Instalación", "body": "fail2ban-client --version"}, {"h": "Paso 1: Crear el Archivo Local", "body": "sudo cp /etc/fail2ban/jail.conf /etc/fail2ban/jail.local"}, {"h": "Paso 2: Configurar SSH (Protección Básica)", "body": "sudo nano /etc/fail2ban/jail.local\n\nenabled = true\nport = ssh\nfilter = sshd\nlogpath = /var/log/auth.log\nmaxretry = 5\nbantime = 600\nfindtime = 600\n\n• maxretry: Número de intentos fallidos permitidos antes de bloquear la IP.\n• bantime: Tiempo en segundos que una IP permanecerá bloqueada (10 minutos en este caso).\n• findtime: Ventana de tiempo en la que se cuentan los intentos fallidos (10 minutos)."}, {"h": "Paso 3: Reiniciar Fail2Ban", "body": "sudo systemctl restart fail2ban"}, {"h": "Verificar el Estado", "body": "sudo fail2ban-client status"}, {"h": "Monitorear Intentos Bloqueados", "body": "sudo fail2ban-client status sshd"}, {"h": "Habilitar Notificaciones por Correo", "body": "Edita el archivo local:\n\nsudo nano /etc/fail2ban/jail.local\n\n[DEFAULT]\naction = %(action_mwl)s\nsender = fail2ban@tudominio.com\ndestemail = admin@tudominio.com\nmta = sendmail\n\n• action: Define el nivel de información enviada (incluye los logs).\n• destemail: Tu dirección de correo para recibir alertas."}, {"h": "Proteger Otros Servicios", "body": "enabled = true\nport = http,https\nfilter = apache-auth\nlogpath = /var/log/apache2/error.log\nmaxretry = 3"}, {"h": "Crear Filtros Personalizados", "body": "• Crea un nuevo archivo de filtro:\n\nsudo nano /etc/fail2ban/filter.d/mi_servicio.conf\n\n• Agrega una expresión regular para detectar intentos fallidos:\n\n[Definition]\nfailregex = <HOST> - - .* 401\n\n• Configura la jail correspondiente en jail.local."}, {"h": "Probar Fail2Ban", "body": "Si necesitas desbloquear una IP (porque, bueno, a veces el portero se equivoca):\n\nsudo fail2ban-client unban IP_DE_BLOQUEO"}, {"h": "Resumen", "body": "• Automatiza la seguridad con bloqueos automáticos.\n• Protege múltiples servicios como SSH, Apache o FTP.\n• Personaliza las reglas según tus necesidades."}]'::jsonb, 'Esperamos que esta guía te haya sido de utilidad. Si tienes dudas durante la implementación, nuestro equipo de soporte técnico está disponible 24/7 para ayudarte.', NULL, '[]'::jsonb, false, true, 'Instalación y Configuración de Fail2Ban para Evitar Fuerza…', 'La seguridad de un servidor Linux es esencial, especialmente contra ataques de fuerza bruta que buscan acceder a servicios como SSH, HTTP o FTP. Fail2Ban…', 0)
