insert into public.blog_posts (slug, locale, category, title, excerpt, published_at, read_time, author, tags, intro, sections, conclusion, image, faqs, featured, published, seo_title, seo_description, sort_order) values ('nginx-caching-rendimiento-servidor', 'es', 'Linux', 'Mejora del Rendimiento de tu Servidor con Caching de Nginx', 'Cuando tu servidor llora por la cantidad de peticiones y tus usuarios ven una página que carga tan lento como un lunes por la mañana, es hora de considerar el uso de caching con Nginx. En esta guía te explicaré qué es el', '2024-12-28', '4 min', 'Equipo Terranode', '["Linux"]'::jsonb, 'Cuando tu servidor llora por la cantidad de peticiones y tus usuarios ven una página que carga tan lento como un lunes por la mañana, es hora de considerar el uso de caching con Nginx. En esta guía te explicaré qué es el caching, cómo configurarlo con Nginx, casos de uso, sus ventajas, y también sus limitaciones. Todo explicado de manera práctica (y con humor, porque hasta los servidores necesitan un respiro 😅).', '[{"h": "Ventajas del Caching", "body": "• Reducción de Carga en el Backend: Ideal para aplicaciones con recursos estáticos o contenidos que no cambian frecuentemente.\n• Velocidad de Respuesta Mejorada: Los usuarios reciben los recursos directamente desde el cache, reduciendo la latencia.\n• Ahorro de Recursos: Menos peticiones al backend significa menos uso de CPU, memoria y base de datos.\n• Escalabilidad: Permite manejar más usuarios simultáneos."}, {"h": "Limitaciones del Caching", "body": "• Contenido Dinámico: No es ideal para datos que cambian constantemente (por ejemplo, carritos de compras).\n• Uso de Espacio en Disco: El almacenamiento del cache puede crecer rápidamente.\n• Actualizaciones: Si el contenido cambia y no se invalida el cache, los usuarios podrían recibir información desactualizada."}, {"h": "Tipos de Caché en Nginx", "body": "• Proxy Cache: Almacena respuestas del backend y las sirve directamente.\n• FastCGI Cache: Ideal para aplicaciones que usan FastCGI (como WordPress con PHP-FPM).\n• Microcaching: Caching de corta duración para contenido muy dinámico."}, {"h": "Empresas y Casos de Uso Comunes", "body": "• E-commerce: Grandes catálogos de productos.\n• Medios y Noticias: Portales con alto tráfico.\n• Blogs y Contenido: Sitios WordPress que sirven artículos o imágenes.\n• Streaming: Para contenido de video estático.\n\n• Manejas datos sensibles como paneles administrativos.\n• Tus usuarios necesitan interacciones personalizadas (carritos de compras, dashboards)."}, {"h": "Paso 1: Habilitar Proxy Cache", "body": "• /var/cache/nginx: Ruta donde se almacenará el cache.\n• keys_zone: Define una zona de memoria para las claves del cache.\n• max_size: Tamaño máximo del cache.\n• inactive: Tiempo que un objeto permanecerá en el cache si no es solicitado."}, {"h": "Paso 2: Configurar una Zona de Cache", "body": "location / {\n proxy_cache cache_zone;\n proxy_pass http://backend;\n proxy_set_header Host $host;\n proxy_set_header X-Real-IP $remote_addr;\n proxy_cache_valid 200 302 10m;\n proxy_cache_valid 404 1m;\n add_header X-Cache-Status $upstream_cache_status;\n }\n}\n\n• proxy_cache: Define la zona de cache a usar.\n• proxy_cache_valid: Tiempo de vida del cache basado en códigos de estado HTTP.\n• X-Cache-Status: Permite ver si un recurso fue servido desde el cache (HIT o MISS)."}, {"h": "Paso 2: Configurar el Bloque de FastCGI", "body": "location ~ \\.php$ {\n include fastcgi_params;\n fastcgi_pass unix:/run/php/php7.4-fpm.sock;\n fastcgi_cache fastcgi_cache_zone;\n fastcgi_cache_valid 200 10m;\n fastcgi_cache_valid 404 1m;\n add_header X-FastCGI-Cache $upstream_cache_status;\n }\n}"}, {"h": "Microcaching para Contenido Dinámico", "body": "Ejemplo de configuración:\n\n• proxy_cache_valid 200 1s: Guarda respuestas exitosas por 1 segundo.\n• proxy_cache_bypass: Evita el cache si existe una cookie de sesión."}, {"h": "Verificar el Estado del Cache", "body": "• HIT: El recurso fue servido desde el cache.\n• MISS: El recurso fue solicitado al backend."}, {"h": "Resumen", "body": "• Usa proxy cache para contenido estático y respuestas de backend.\n• Implementa FastCGI cache en aplicaciones PHP.\n• Prueba microcaching para contenido dinámico con alta demanda."}]'::jsonb, 'Esperamos que esta guía te haya sido de utilidad. Si tienes dudas durante la implementación, nuestro equipo de soporte técnico está disponible 24/7 para ayudarte.', NULL, '[]'::jsonb, false, true, 'Mejora del Rendimiento de tu Servidor con Caching de Nginx', 'Cuando tu servidor llora por la cantidad de peticiones y tus usuarios ven una página que carga tan lento como un lunes por la mañana, es hora de considerar…', 0)
