insert into public.blog_posts (slug, locale, category, title, excerpt, published_at, read_time, author, tags, intro, sections, conclusion, image, faqs, featured, published, seo_title, seo_description, sort_order) values ('detectar-rootkits-rkhunter-chkrootkit', 'es', 'Linux', 'Guía Completa para Detectar Rootkits con RKHunter y Chkrootkit', 'La seguridad en los servidores Linux es una prioridad absoluta, y los rootkits son uno de los mayores enemigos a combatir. Estos pequeños pero peligrosos programas maliciosos buscan ocultarse en tu sistema para realizar ', '2024-12-29', '4 min', 'Equipo Terranode', '["Linux"]'::jsonb, 'La seguridad en los servidores Linux es una prioridad absoluta, y los rootkits son uno de los mayores enemigos a combatir. Estos pequeños pero peligrosos programas maliciosos buscan ocultarse en tu sistema para realizar acciones no autorizadas. Por suerte, herramientas como RKHunter y Chkrootkit están aquí para ayudarte a detectarlos antes de que causen estragos. Esta guía completa te llevará paso a paso por el…', '[{"h": "Controlar el sistema", "body": "Ejemplo clásico: Un rootkit puede estar robando datos confidenciales de tu servidor mientras tú piensas que todo está bien. Espeluznante, ¿no? 🚫"}, {"h": "Paso 1: Instalación de RKHunter", "body": "sudo apt update\nsudo apt install rkhunter -y\n\nsudo yum install epel-release -y\nsudo yum install rkhunter -y"}, {"h": "Paso 2: Instalación de Chkrootkit", "body": "sudo apt install chkrootkit -y\n\nsudo yum install chkrootkit -y"}, {"h": "Actualizar las Bases de Datos", "body": "sudo rkhunter --update\n\nsudo rkhunter --propupd"}, {"h": "Realizar un Escaneo Completo", "body": "sudo rkhunter --checkall\n\nPro tip: Si ves demasiados \"[ Warning ]\", no entres en pánico. La mayoría son falsos positivos. Verifica los resultados detalladamente."}, {"h": "Revisar los Resultados", "body": "/var/log/rkhunter.log"}, {"h": "Realizar un Escaneo Básico", "body": "sudo chkrootkit\n\nHumor tech: Si aparece \"INFECTED\" en el escaneo, no es el momento de gritar ¡Apocalipsis! Es solo una advertencia que requiere investigación. 😅"}, {"h": "Escanear Directorios Específicos", "body": "sudo chkrootkit /ruta/directorio"}, {"h": "Crear un Cron Job para RKHunter", "body": "sudo crontab -e\n\n0 3 * * * /usr/bin/rkhunter --checkall --quiet"}, {"h": "Crear un Cron Job para Chkrootkit", "body": "30 3 * * * /usr/sbin/chkrootkit"}, {"h": "Servidor de Base de Datos", "body": "Humor tech: Un servidor sin escaneos es como un castillo sin guardias. ¡Está pidiendo que lo invadan! 🏰"}, {"h": "Resumen", "body": "Instala y configura ambas herramientas para escaneos regulares. Automatiza las tareas con Cron para no olvidarte. Analiza los resultados con cuidado para evitar falsos positivos.\n\n🛡️ Recuerda: La seguridad es un proceso continuo, no un destino. Mantén a tus \"detectives\" activos y tu sistema protegido."}]'::jsonb, 'Esperamos que esta guía te haya sido de utilidad. Si tienes dudas durante la implementación, nuestro equipo de soporte técnico está disponible 24/7 para ayudarte.', NULL, '[]'::jsonb, false, true, 'Guía Completa para Detectar Rootkits con RKHunter y Chkrootkit', 'La seguridad en los servidores Linux es una prioridad absoluta, y los rootkits son uno de los mayores enemigos a combatir. Estos pequeños pero peligrosos…', 0)
