insert into public.blog_posts (slug, locale, category, title, excerpt, published_at, read_time, author, tags, intro, sections, conclusion, image, faqs, featured, published, seo_title, seo_description, sort_order) values ('como-implementar-un-proyecto-de-laravel-en-un-vps', 'es', 'Programming', 'Cómo Implementar un Proyecto de Laravel en un VPS', 'Configurar un proyecto de Laravel en un VPS puede sonar como desactivar una bomba: estresante, pero emocionante si sabes lo que haces. En esta guía paso a paso aprenderás a configurar todo, desde el VPS recién salido del', '2024-12-29', '4 min', 'Equipo Terranode', '["Programming"]'::jsonb, 'Configurar un proyecto de Laravel en un VPS puede sonar como desactivar una bomba: estresante, pero emocionante si sabes lo que haces. En esta guía paso a paso aprenderás a configurar todo, desde el VPS recién salido del horno hasta que tu aplicación esté funcionando como un Ferrari bien afinado. ¡Y lo mejor! Lo haremos con humor y algunos chistes tech para hacer más ameno el proceso. 😎', '[{"h": "Actualizar el Sistema", "body": "sudo apt update && sudo apt upgrade -y"}, {"h": "Crear un Usuario no Root", "body": "adduser tu_usuario\nusermod -aG sudo tu_usuario\n\nsu - tu_usuario"}, {"h": "Deshabilitar el Login para Root", "body": "Edita el archivo de configuración de SSH:\n\nsudo nano /etc/ssh/sshd_config\n\nPermitRootLogin no\n\nsudo systemctl restart ssh"}, {"h": "Configurar el Firewall", "body": "sudo ufw allow OpenSSH\nsudo ufw enable\n\nsudo ufw status"}, {"h": "Instalar Apache", "body": "sudo apt install apache2 -y\n\nsudo systemctl enable apache2\nsudo systemctl start apache2"}, {"h": "Instalar MySQL", "body": "sudo apt install mysql-server -y\n\nsudo mysql_secure_installation\n\nsudo mysql -u root -p\nCREATE DATABASE laravel_db;\nGRANT ALL ON laravel_db.* TO ''laravel_user''@''localhost'' IDENTIFIED BY ''tu_contraseña_segura'';\nFLUSH PRIVILEGES;\nEXIT;"}, {"h": "Instalar PHP", "body": "sudo apt install php libapache2-mod-php php-mysql php-cli php-curl php-mbstring php-xml php-zip -y\n\nphp -v"}, {"h": "Instalar Composer", "body": "sudo apt install composer -y\n\ncomposer -v"}, {"h": "Descargar el Proyecto de Laravel", "body": "cd /var/www/\ngit clone https://github.com/tu_usuario/tu_proyecto_laravel.git\n\ncd tu_proyecto_laravel\ncomposer install"}, {"h": "Configurar el Archivo .env", "body": "cp .env.example .env\n\nDB_CONNECTION=mysql\nDB_HOST=127.0.0.1\nDB_PORT=3306\nDB_DATABASE=laravel_db\nDB_USERNAME=laravel_user\nDB_PASSWORD=tu_contraseña_segura\n\nphp artisan key:generate"}, {"h": "Migrar la Base de Datos", "body": "php artisan migrate"}, {"h": "Paso 4: Configurar Apache para Laravel", "body": "sudo nano /etc/apache2/sites-available/tu_proyecto_laravel.conf\n\n<VirtualHost *:80>\n ServerName tu_dominio.com\n DocumentRoot /var/www/tu_proyecto_laravel/public\n<Directory /var/www/tu_proyecto_laravel/public>\n AllowOverride All\n Require all granted\n </Directory>\nErrorLog ${APACHE_LOG_DIR}/error.log\n CustomLog ${APACHE_LOG_DIR}/access.log combined\n</VirtualHost>\n\n<Directory /var/www/tu_proyecto_laravel/public>\n AllowOverride All\n Require all granted\n </Directory>\n\nErrorLog ${APACHE_LOG_DIR}/error.log\n CustomLog ${APACHE_LOG_DIR}/access.log combined\n</VirtualHost>\n\nsudo a2ensite tu_proyecto_laravel.conf\nsudo a2enmod rewrite\nsudo systemctl restart apache2"}, {"h": "Paso 5: Configurar Certificado SSL", "body": "Instala Certbot:\n\nsudo apt install certbot python3-certbot-apache -y\n\nsudo certbot --apache -d tu_dominio.com\n\nsudo crontab -e\n\n0 0 * * * certbot renew --quiet"}, {"h": "Paso 6: Configurar Permisos", "body": "sudo chown -R www-data:www-data /var/www/tu_proyecto_laravel\nsudo chmod -R 775 /var/www/tu_proyecto_laravel/storage\nsudo chmod -R 775 /var/www/tu_proyecto_laravel/bootstrap/cache"}, {"h": "Paso 7: Acceder a tu Aplicación", "body": "Humor tech: Si algo no funciona, revisa los logs. Son como el diario de tu servidor: siempre tiene la respuesta. 📖"}, {"h": "Resumen", "body": "• Actualiza y asegura tu VPS.\n• Instala LAMP Stack.\n• Configura Laravel con Composer y .env.\n• Ajusta Apache para servir tu aplicación.\n• Habilita SSL para mayor seguridad."}]'::jsonb, 'Esperamos que esta guía te haya sido de utilidad. Si tienes dudas durante la implementación, nuestro equipo de soporte técnico está disponible 24/7 para ayudarte.', NULL, '[]'::jsonb, false, true, 'Cómo Implementar un Proyecto de Laravel en un VPS', 'Configurar un proyecto de Laravel en un VPS puede sonar como desactivar una bomba: estresante, pero emocionante si sabes lo que haces. En esta guía paso a…', 0)
