insert into public.blog_posts (slug, locale, category, title, excerpt, published_at, read_time, author, tags, intro, sections, conclusion, image, faqs, featured, published, seo_title, seo_description, sort_order) values ('como-montar-un-servidor-de-node-js-en-nginx', 'es', 'VPS', 'Cómo Montar un Servidor de Node.js en Nginx', 'Node.js es conocido por su velocidad y eficiencia, pero para manejar aplicaciones web en producción, necesitas algo más robusto al frente: Nginx . Esta guía te llevará paso a paso para configurar un servidor de Node.js d', '2024-12-29', '3 min', 'Equipo Terranode', '["VPS"]'::jsonb, 'Node.js es conocido por su velocidad y eficiencia, pero para manejar aplicaciones web en producción, necesitas algo más robusto al frente: Nginx. Esta guía te llevará paso a paso para configurar un servidor de Node.js detras de Nginx, incluyendo el manejo de puertos, configuración del firewall y optimización para producción. ¡Empezamos! 🚀', '[{"h": "Requisitos Previos", "body": "• Un VPS funcionando (Ubuntu o Debian).\n• Acceso SSH al servidor.\n• Node.js y npm instalados.\n• Nginx instalado."}, {"h": "Instalar Node.js", "body": "• Actualiza el sistema:\n\nsudo apt update && sudo apt upgrade -y\n\n• Instala Node.js desde el repositorio oficial:\n\ncurl -fsSL https://deb.nodesource.com/setup_18.x | sudo -E bash -\nsudo apt install -y nodejs\n\n• Verifica la instalación:\n\nnode -v\nnpm -v"}, {"h": "Instalar Nginx", "body": "• Instala Nginx:\n\nsudo apt install nginx -y\n\n• Habilita y verifica el servicio:\n\nsudo systemctl enable nginx\nsudo systemctl start nginx\nsudo systemctl status nginx"}, {"h": "Paso 2: Configurar tu Aplicación Node.js", "body": "• Crea un directorio para tu proyecto:\n\nmkdir ~/mi_app_node\ncd ~/mi_app_node\n\n• Inicializa el proyecto Node.js:\n\nnpm init -y\n\n• Instala Express.js:\n\nnpm install express\n\n• Crea un archivo index.js con el siguiente contenido:\n\nconst express = require(''express'');\nconst app = express();\nconst PORT = 3000;\napp.get(''/'', (req, res) => {\n res.send(''¡Servidor Node.js funcionando correctamente!'');\n});\napp.listen(PORT, () => {\n console.log(`Servidor corriendo en http://localhost:${PORT}`);\n});\n\napp.get(''/'', (req, res) => {\n res.send(''¡Servidor Node.js funcionando correctamente!'');\n});\n\napp.listen(PORT, () => {\n console.log(`Servidor corriendo en http://localhost:${PORT}`);\n});\n\n• Inicia el servidor:\n\nnode index.js\n\nPro tip: Usa pm2 para mantener el servidor activo incluso si cierras la sesión SSH:\n\nsudo npm install -g pm2\npm2 start index.js\npm2 startup"}, {"h": "Paso 3: Configurar Nginx como Proxy Reverso", "body": "• Crea un archivo de configuración para tu sitio:\n\nsudo nano /etc/nginx/sites-available/mi_app_node\n\n• Agrega la configuración siguiente:\n\nserver {\n listen 80;\n server_name tu_dominio.com; # Cambia esto por tu dominio o IP\nlocation / {\n proxy_pass http://localhost:3000;\n proxy_http_version 1.1;\n proxy_set_header Upgrade $http_upgrade;\n proxy_set_header Connection ''upgrade'';\n proxy_set_header Host $host;\n proxy_cache_bypass $http_upgrade;\n }\n}\n\nlocation / {\n proxy_pass http://localhost:3000;\n proxy_http_version 1.1;\n proxy_set_header Upgrade $http_upgrade;\n proxy_set_header Connection ''upgrade'';\n proxy_set_header Host $host;\n proxy_cache_bypass $http_upgrade;\n }\n}\n\n• Activa la configuración:\n\nsudo ln -s /etc/nginx/sites-available/mi_app_node /etc/nginx/sites-enabled/\n\n• Verifica la configuración de Nginx:\n\nsudo nginx -t\n\n• Reinicia Nginx:\n\nsudo systemctl restart nginx\n\nHumor tech: Sin proxy reverso, tu servidor está desnudo ante el mundo. ¡Ponle esa capa protectora! 🦸"}, {"h": "Paso 4: Configurar el Firewall", "body": "• Permite solo el tráfico HTTP y HTTPS:\n\nsudo ufw allow OpenSSH\nsudo ufw allow ''Nginx Full''\nsudo ufw enable\n\n• Verifica el estado del firewall:\n\nsudo ufw status"}, {"h": "Paso 5: Configurar SSL con Let''s Encrypt", "body": "• Instala Certbot:\n\nsudo apt install certbot python3-certbot-nginx -y\n\n• Genera el certificado:\n\nsudo certbot --nginx -d tu_dominio.com\n\n• Verifica la renovación automática:\n\nsudo certbot renew --dry-run\n\nPro tip: HTTPS no solo protege a los usuarios, también mejora el SEO de tu sitio. 📈"}, {"h": "Paso 6: Optimizar Nginx para Producción", "body": "• Ajusta los tiempos de espera para evitar desconexiones:\n\nserver {\n ...\n proxy_read_timeout 90s;\n proxy_connect_timeout 90s;\n proxy_send_timeout 90s;\n}\n\n• Habilita la compresión Gzip:\n\nsudo nano /etc/nginx/nginx.conf\n\ngzip on;\ngzip_types text/plain text/css application/json application/javascript text/xml application/xml application/xml+rss text/javascript;\n\nsudo systemctl restart nginx"}, {"h": "Resumen", "body": "• Instala Node.js y Nginx.\n• Crea y prueba tu aplicación Node.js.\n• Configura Nginx como proxy reverso.\n• Asegura tu servidor con un firewall.\n• Protege tu sitio con SSL.\n• Optimiza Nginx para producción."}]'::jsonb, 'Esperamos que esta guía te haya sido de utilidad. Si tienes dudas durante la implementación, nuestro equipo de soporte técnico está disponible 24/7 para ayudarte.', NULL, '[]'::jsonb, false, true, 'Cómo Montar un Servidor de Node.js en Nginx', 'Node.js es conocido por su velocidad y eficiencia, pero para manejar aplicaciones web en producción, necesitas algo más robusto al frente: Nginx . Esta…', 0)
